example:
service jobs {
    @rateLimit(SignupLimit, key: clientIp)   // ✗ a `call` has no router step
    on call(n: Int) -> Effect[Int] by Caller { … }
}

service jobs {
    on call(n: Int) -> Effect[Int] by Caller given SignupLimit {   // ✓ ask the limiter
        let ok <- SignupLimit.allow("jobs")
        Effect.pure(if ok { 1 } else { 0 })
    }
}
